class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        operations = 0
        n = len(word)

        # Helper function to check if two characters are almost-equal
        def almost_equal(a, b):
            return a == b or ord(a) - ord(b) == 1 or ord(b) - ord(a) == 1

        # Iterate through the string and check adjacent characters
        for i in range(1, n):
            if almost_equal(word[i], word[i - 1]):
                operations += 1
                # To avoid counting the same pairs multiple times, we assume we change the current character
                # For this simulation, we can simulate changing word[i] to a character not conflicting with previous
                # This character will be 'c' skipping 'word[i-1]' and the adjacent one
                if word[i - 1] != 'a':
                    word = word[:i] + 'a' + word[i + 1:]  # change to 'a' if possible
                else:
                    word = word[:i] + 'b' + word[i + 1:]  # change to 'b' if previous is 'a'

        return operations
